\version "2.27.2"
% automatically converted by musicxml2ly from 45f-Repeats-InvalidEndings.xml
\pointAndClickOff

\header {
  texidoc = "A stress test with a combination of <repeat> and <ending> elements
    that don't make sense. The displayed result depends on the sanitizing
    possibilities of the application that handles the input.

    Bar 2 starts and ends with <ending number=\"1, 2, 3\">. Bar 3 starts and
    ends with <ending number=\"2\"> (where the right element is of type
    'discontinue'); there is no <repeat> element between bars 2 and 3. Finally,
    at the end of bar 4 there is a both a <repeat direction=\"backward\"> and a
    <ending type=\"stop\"> element.

    Bar 6 starts a repeat, bar 7 start and ends a prima volta bracket, but the
    corresponding repeat bar is between bars 8 and 9, followed by a seconda
    volta bracket starting and ending in bar 9.

    Another invalid ‘pair’ is <ending type=\"start\"> at the beginning of bar 12
    and <ending type=\"discontinue\"> at the end of bar 13."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    doubleRepeatBarType = ":|.|:"
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \repeat volta 4 {
    \clef "treble" \time 4/4 \key c \major R1 | % 1
    \alternative {
      \volta 1,2,3 {
        R1 | % 2
      }
      \volta 2 {
        R1 | % 3
      }
    }
  }
  R1 | % 4
  R1 | % 5
  \repeat volta 2 {
    R1 | % 6
    \alternative {
      \volta 1 {
        R1 | % 7
        R1 | % 8
      }
      \volta 2 {
        R1 | % 9

        \barNumberCheck #10
      }
    }
  }
  R1 | % 10
  R1 | % 11
  R1 | % 12
  R1 | % 13
  \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
